from griffe.extensions import Extension
from griffe.docstrings.dataclasses import Docstring
import griffe

class AppendCheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_members_collected(self, obj):
        """Called after members are collected for a module."""
        for member in obj.members.values():
