                    member.docstring.value += " [checked]"
                else:
                    member.docstring = Docstring(" [checked]")
            if hasattr(member, 'members'):
                self.on_members_collected(member)

extensions = [AppendCheckedExtension()]
package = griffe.load("mypkg", extensions=extensions)

